from pathlib import Path
from html import escape
root = Path(__file__).resolve().parent
slides=[]
def slide(label,title,body,cls=''):
    slides.append(f'<section class="slide {cls}" aria-label="{escape(title)}"><header><span>olhar<span class="gold">.</span></span><span>{label}</span></header>{body}<footer><span>OLHAR SELVAGEM · PROJETO MOBILE</span><span>{len(slides)+1:02d}</span></footer></section>')
def heading(kicker,title,desc=''):
    return f'<div class="eyebrow">{kicker}</div><h1>{title}</h1>'+ (f'<p class="lead">{desc}</p>' if desc else '')
def card(n,t,p):return f'<article class="card"><span class="number">{n}</span><h2>{t}</h2><p>{p}</p></article>'
def code(s):return '<pre><code>'+escape(s)+'</code></pre>'
slide('REGISTRAR • LOCALIZAR • INFORMAR','Olhar Selvagem', '<div class="cover"><div>'+heading('APLICATIVO DE REGISTRO DE ANIMAIS','Olhar<br>Selvagem<span class="gold">.</span>','Uma foto e uma localização para dar visibilidade aos encontros com animais potencialmente perigosos.')+'<div class="pills"><span>React Native + Expo</span><span>SQLite</span><span>Recursos do celular</span></div></div><div class="cover-art"><div class="ring r1"></div><div class="ring r2"></div><div class="pin">◎</div><div class="coordinates">FOTO + LOCAL + DATA</div><p>Observar.<br>Registrar.<br>Compartilhar.</p></div></div>', 'dark')
slide('01 / A PROPOSTA','Informação sobre o animal e o lugar',heading('POR QUE ESTE PROJETO?','Informação sobre o animal<br>e o lugar.')+'<div class="grid three">'+card('01','Registrar','Fotografar o animal e associar a imagem à localização e à data do encontro.')+card('02','Compartilhar','A proposta é permitir que outras pessoas vejam a foto do animal e onde ele foi encontrado.')+card('03','Consultar','Ajudar a comunidade a conhecer os avistamentos e os possíveis riscos de uma região.')+'</div><div class="note"><b>Cenários que motivam a ideia:</b> encontros com jacarés em regiões dos Estados Unidos e com animais peçonhentos ou perigosos na Austrália.</div><p class="small">O protótipo demonstra o registro local. O compartilhamento entre usuários depende de uma futura integração com servidor.</p>')
slide('02 / ACESSO','Login e modo de demonstração',heading('AUTENTICAÇÃO','Login com a API do professor Kleber.','O app envia usuário e senha para a API e restaura os dados da sessão ao ser aberto novamente.')+'<div class="grid two">'+card('API','Integração preparada','Uma requisição POST envia as credenciais. A resposta identifica o usuário autenticado.')+card('DEMO','Apresentação sem bloqueio','Diante do erro de CORS relatado no navegador, usamos o modo de demonstração para apresentar os recursos do app.')+'</div><div class="note"><b>O que é CORS?</b> Uma regra do navegador que depende da autorização do servidor para chamadas entre origens diferentes. O modo demo cria uma sessão local e não autentica na API.</div>')
steps=[
('Começar pela galeria.','A tela inicial reúne os registros feitos no aplicativo.', [('Galeria vazia','Antes do primeiro uso, a tela convida a registrar um animal.'),('Novo encontro','Toque em “Registrar meu primeiro animal” ou no botão +.')], 'Imagem 1 · Início do fluxo'),
('Escolher como fotografar.','O usuário inicia um registro com uma imagem do animal.', [('Câmera','“Abrir câmera” permite tirar uma foto naquele momento.'),('Galeria','Também é possível escolher uma imagem já existente no aparelho.'),('Localização','O app solicita acesso à localização para associar as coordenadas ao encontro.')], 'Imagem 2 · Captura e localização'),
('Conferir a imagem.','A foto selecionada aparece antes de salvar o registro.', [('Prévia','O usuário confere se a imagem representa o encontro.'),('Troca da foto','Se necessário, pode tirar outra foto ou escolher uma nova imagem.')], 'Imagem 3 · Foto selecionada · animal doméstico usado no teste'),
('Salvar e receber o aviso.','Após salvar, o app apresenta os detalhes e uma notificação local.', [('Registro completo','A foto fica associada à latitude, à longitude e à data.'),('Confirmação','“Registro salvo!” demonstra a integração com as notificações do celular.')], 'Imagem 4 · Detalhes e notificação recebida'),
('Consultar o encontro.','O registro salvo passa a fazer parte da galeria do aplicativo.', [('Visualização','O cartão mostra a foto, a data e as coordenadas.'),('Detalhes e exclusão','Abra o encontro para consultar seus dados. A versão atual também permite apagar a foto com confirmação.')], 'Imagem 5 · Galeria com um registro')]
for i,(title,desc,items,caption) in enumerate(steps,1):
    details=''.join(f'<div class="step-item"><span>{j:02}</span><div><h2>{t}</h2><p>{p}</p></div></div>' for j,(t,p) in enumerate(items,1))
    slide(f'PASSO {i} / 5',title,f'<div class="walkthrough"><div>{heading("NA PRÁTICA",title,desc)}{details}</div><figure><img src="imagens/{i}.jpeg" alt="{escape(caption)}"><figcaption>{caption}</figcaption></figure></div>')
slide('03 / ARMAZENAMENTO','O registro continua salvo ao fechar o app',heading('SQLITE + ARQUIVOS LOCAIS','Fechou o app?<br>O registro continua salvo.')+'<div class="grid two">'+card('SQLite','Dados do encontro','O banco olhar-selvagem.db guarda ID, caminho da foto, latitude, longitude e data. Ao reabrir, o app consulta a tabela animals.')+card('Arquivo','A imagem no celular','A foto é copiada para a pasta interna animals/. O SQLite guarda o caminho desse arquivo, e não a imagem em si.')+'</div><div class="flow"><span>Foto na pasta do app</span><b>→</b><span>Caminho + dados no SQLite</span><b>→</b><span>Galeria ao reabrir</span></div><p class="small">No celular: SQLite. Na versão web: IndexedDB. Os registros são locais e não são enviados automaticamente a outros usuários.</p>')
slide('04 / NOTIFICAÇÕES','Uma confirmação a cada novo registro',heading('DEMONSTRAÇÃO DO RECURSO','Salvou um registro?<br>O app envia uma notificação.','A notificação local confirma a ação e demonstra o uso do recurso no celular.')+'<div class="notification"><span class="bell">♪</span><div><h2>Registro salvo!</h2><p>Eba! Mais um encontro guardado na sua galeria.</p></div><span class="small">agora</span></div><div class="grid two compact">'+card('QUANDO','Depois de salvar','O app primeiro grava o registro e, em seguida, solicita a notificação com som padrão.')+card('CONDIÇÃO','Permissão do usuário','O aviso e o som dependem da autorização e das configurações do celular. A foto permanece salva se a notificação falhar.')+'</div><p class="small">Nesta demonstração, o aviso é disparado pelo próprio aparelho. Alertas sobre avistamentos de outras pessoas ficam como evolução do projeto.</p>')
slide('05 / CÓDIGO · CÂMERA','Pedir autorização para usar a câmera',heading('PERMISSÕES · EXEMPLO SIMPLIFICADO','Antes da foto, pedimos permissão.')+code("import { Camera } from 'expo-camera';\n\nlet permission = await Camera.getCameraPermissionsAsync();\nif (!permission.granted && permission.canAskAgain) {\n  permission = await Camera.requestCameraPermissionsAsync();\n}\n\nif (!permission.granted) return;")+'<div class="explanation"><b>Como funciona?</b><p>Primeiro consultamos a permissão. Se ainda não foi concedida e o sistema permite perguntar, mostramos a solicitação. A câmera só pode ser usada quando o acesso é autorizado.</p></div><p class="small">Se o acesso estiver bloqueado, o app orienta a abertura das configurações. Base: StartupPermissions.native.tsx.</p>')
slide('06 / CÓDIGO · NOTIFICAÇÕES','Pedir autorização para enviar avisos',heading('PERMISSÕES · EXEMPLO SIMPLIFICADO','O usuário também autoriza os avisos.')+code("import * as Notifications from 'expo-notifications';\nimport { prepareNotifications } from '@/services/notifications';\n\nawait prepareNotifications();\nlet permission = await Notifications.getPermissionsAsync();\nif (!permission.granted && permission.canAskAgain) {\n  permission = await Notifications.requestPermissionsAsync();\n}")+'<div class="explanation"><b>Como funciona?</b><p>Preparamos o canal no Android, consultamos a autorização e solicitamos acesso quando necessário. Depois de salvar um encontro, o app usa essa permissão para exibir a notificação local.</p></div><p class="small">A preparação usa o canal padrão se a criação do canal personalizado falhar no Expo Go. Base: notifications.native.ts e StartupPermissions.native.tsx.</p>')
css='''
:root{--forest:#153b2f;--ink:#18392e;--paper:#f7f8f3;--gold:#dea76e;--muted:#62756a}*{box-sizing:border-box}body{margin:0;background:#16271f;font-family:Arial,Helvetica,sans-serif;color:var(--ink)}.slide{position:relative;width:1280px;height:720px;padding:40px 64px 48px;background:var(--paper);overflow:hidden;flex-shrink:0}header,footer{display:flex;justify-content:space-between;align-items:center}header{margin-bottom:36px;color:var(--muted);font-size:12px;letter-spacing:2px;font-weight:bold}header>span:first-child{font-size:32px;letter-spacing:-2px;color:var(--forest)}footer{position:absolute;bottom:25px;left:64px;right:64px;border-top:1px solid #d7e1d7;padding-top:13px;font-size:10px;letter-spacing:1.7px;color:var(--muted)}.gold{color:var(--gold)}.eyebrow{font-size:12px;letter-spacing:2.5px;color:#508064;font-weight:bold;margin-bottom:14px}h1{font-size:44px;letter-spacing:-1.5px;line-height:1.08;margin:0 0 20px;max-width:1080px}h2{font-size:24px;letter-spacing:-.5px;margin:12px 0}p{font-size:20px;line-height:1.45;margin:0;color:var(--muted)}.lead{font-size:23px;max-width:920px;margin-bottom:28px}.grid{display:grid;gap:22px;margin-top:30px}.three{grid-template-columns:repeat(3,1fr)}.two{grid-template-columns:repeat(2,1fr)}.card{border:1px solid #dce5da;border-radius:18px;background:#fff;padding:25px}.number{color:#528368;font-size:13px;font-weight:bold;letter-spacing:1.4px}.card p{font-size:19px}.note{margin-top:24px;border-left:4px solid var(--gold);padding:15px 20px;background:#eeeede;font-size:19px;line-height:1.45}.small{font-size:14px;line-height:1.45;margin-top:18px}.cover{display:grid;grid-template-columns:1.3fr 1fr;gap:50px;align-items:center;height:510px}.cover h1{font-size:92px;letter-spacing:-4px}.cover .lead{max-width:610px;font-size:25px}.dark{background:#12382b;color:var(--paper)}.dark header>span:first-child,.dark p{color:#e0e9dd}.dark header,.dark footer,.dark .eyebrow{color:#a6c4ab}.dark footer{border-color:#47624f}.pills{display:flex;gap:10px;margin-top:28px}.pills span{font-size:13px;border:1px solid #68846d;padding:10px 13px;border-radius:24px}.cover-art{height:430px;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid #58775e;border-radius:200px 200px 25px 25px;background:#214e39;overflow:hidden}.cover-art p{font-size:38px;font-weight:bold;line-height:1.16;z-index:1}.pin{font-size:90px;color:var(--gold);z-index:1}.coordinates{font-size:11px;letter-spacing:3px;color:#bdcbb4;margin:12px 0 22px;z-index:1}.ring{position:absolute;width:360px;height:360px;border:1px solid #688266;border-radius:50%;opacity:.3}.r1{left:-130px;top:50px}.r2{right:-150px;bottom:-100px}.walkthrough{display:grid;grid-template-columns:1fr 390px;gap:65px;align-items:center;margin-top:-12px}.walkthrough h1{font-size:48px}.walkthrough .lead{font-size:24px;margin-bottom:30px}.step-item{display:flex;gap:18px;margin-top:24px;max-width:650px}.step-item>span{background:#dce8dc;color:#396b4b;border-radius:12px;padding:12px;height:45px;font-weight:bold}.step-item h2{margin:0 0 6px;font-size:24px}.step-item p{font-size:20px}figure{margin:0;text-align:center}figure img{display:block;height:540px;width:243px;object-fit:contain;border-radius:15px;margin:auto;box-shadow:0 14px 25px #173d2c22}figcaption{font-size:11px;color:var(--muted);margin:12px auto 0;max-width:370px}.flow{display:flex;gap:17px;align-items:center;justify-content:center;margin-top:28px}.flow span{background:#dfe9dd;border-radius:10px;padding:18px;font-size:19px}.flow b{color:#60906c}.notification{display:flex;align-items:center;gap:22px;background:var(--forest);color:white;border-radius:20px;padding:24px 30px;max-width:900px}.notification h2{margin:0 0 4px}.notification p{color:#c7d9c9}.notification .small{margin:0 0 0 auto;color:#b3c8b5}.bell{font-size:48px;color:var(--gold)}.compact{margin-top:22px}.compact .card{padding:20px}.compact h2{font-size:21px}.compact p{font-size:18px}pre{background:#15382e;color:#ecf2df;padding:26px 30px;border-radius:16px;font-size:21px;line-height:1.5;margin:22px 0 20px;white-space:pre-wrap}code{font-family:'DejaVu Sans Mono',monospace}.explanation{border-left:4px solid var(--gold);padding-left:20px}.explanation b{font-size:21px}.explanation p{font-size:20px;margin-top:8px}nav{position:fixed;bottom:10px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;background:#10271fe8;padding:8px 16px;border-radius:30px;z-index:3;color:white;font-size:12px}nav button{cursor:pointer;background:transparent;color:white;border:1px solid #799484;border-radius:15px;padding:6px 12px}#stage{position:fixed;left:50%;top:50%;transform-origin:center;}.slide{display:none}.slide.active{display:block}@page{size:1280px 720px;margin:0}@media print{body{background:white}#stage{position:static;transform:none!important}.slide{display:block!important;break-after:page;page-break-after:always}.slide:last-child{break-after:auto;page-break-after:auto}nav{display:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
'''
script='''const slides=[...document.querySelectorAll('.slide')];let current=0;function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,n)=>s.classList.toggle('active',n===current));document.querySelector('#count').textContent=`${current+1} / ${slides.length}`;history.replaceState(null,'',`#${current+1}`);}function resize(){document.querySelector('#stage').style.transform=`translate(-50%,-50%) scale(${Math.min(innerWidth/1280,(innerHeight-65)/720)})`;}document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.();};addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1);}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1);}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);});addEventListener('resize',resize);show((parseInt(location.hash.slice(1))||1)-1);resize();'''
html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Olhar Selvagem — Apresentação</title><style>'+css+'</style></head><body><main id="stage">'+''.join(slides)+'</main><nav aria-label="Navegação dos slides"><button id="prev" aria-label="Slide anterior">←</button><span id="count" aria-live="polite"></span><button id="next" aria-label="Próximo slide">→</button><button id="fullscreen">Tela cheia</button></nav><script>'+script+'</script></body></html>'
(root/'index.html').write_text(html,encoding='utf-8')
print(f'{len(slides)} slides criados')
